
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
/* ---------- Real data: dates + store ---------- */
const KEY='prometheus:v1';
const pad=n=>String(n).padStart(2,'0');
const iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
/* a day runs until 4 am, so late nights count for the day you were living */
const dayOf=(t=new Date())=>{const d=new Date(t);if(d.getHours()<4)d.setDate(d.getDate()-1);return iso(d)};
const dObj=x=>new Date(x+'T12:00:00');
const addDays=(x,k)=>{const d=dObj(x);d.setDate(d.getDate()+k);return iso(d)};
const weekStart=x=>addDays(x,-((dObj(x).getDay()+6)%7));
const wkIdx=x=>(dObj(x).getDay()+6)%7;
const fmtDay=x=>{const d=dObj(x);return `${d.toLocaleDateString('en-US',{weekday:'short'})} ${d.getDate()} ${d.toLocaleDateString('en-US',{month:'short'})}`};
const dayShort=x=>dObj(x).toLocaleDateString('en-US',{weekday:'short'}).slice(0,2);
const nowH=()=>{const d=new Date();let h=d.getHours()+d.getMinutes()/60;if(h<4)h+=24;return h};
let TODAY=dayOf();
const thisWeek=()=>{const w=weekStart(TODAY),o=[];for(let d=w;d<=TODAY;d=addDays(d,1))o.push(d);return o};
const daysAgo=d=>Math.round((dObj(TODAY)-dObj(d))/864e5);
const uid=()=>Math.random().toString(36).slice(2,10);
function blankStore(){return {v:1,setup:false,start:null,missRun:0,forfeit:null,questLog:[],avg:Array(12).fill(0),questLast:{},weights:{},sleep:{},workouts:[],checkins:[],days:{},
  tomorrow:null,tmrw:[],goals:[],hq:null,np:null,weeks:{},lastCheckin:0,nudged:{},today:null}}
let D=blankStore();
const DAY=()=>D.days[TODAY]||(D.days[TODAY]={});

const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
/* ---------- Flame sprite (approved: flame-reference-3.gif, 9 frames) ---------- */
const FW=432,FH=528,FN=9,sheetImg=new Image();sheetImg.src=import.meta.env.BASE_URL+'flame.png';
const flames=[];
function addFlame(cv,w){const o={cv,c:cv.getContext('2d')};flames.push(o);sizeFlame(o,w);return o}
function sizeFlame(o,w){const d=Math.min(2,devicePixelRatio||1),h=Math.round(w*FH/FW);o.cv.width=Math.max(1,Math.round(w*d));o.cv.height=Math.max(1,Math.round(h*d));o.cv.style.width=w+'px';o.cv.style.height=h+'px';o.dirty=true}
let lastF=-1;const t0=performance.now();
function loop(now){const f=Math.floor(Math.max(0,now-t0)/90)%FN;if(sheetImg.complete){flames.forEach(o=>{if(f===lastF&&!o.dirty)return;if(!o.cv.offsetParent&&!o.dirty)return;o.dirty=false;const{cv,c}=o;c.clearRect(0,0,cv.width,cv.height);c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';c.drawImage(sheetImg,f*FW,0,FW,FH,0,0,cv.width,cv.height)});lastF=f}flameRAF=null;if(!document.hidden&&flames.some(o=>o.cv.offsetParent))flameRAF=requestAnimationFrame(loop)}
let flameRAF=null;function flameWake(){if(!flameRAF&&!document.hidden)flameRAF=requestAnimationFrame(loop)}
document.addEventListener('visibilitychange',flameWake);

/* ---------- XP + toast ---------- */
let toastT;function toast(t){const e=$('#toast');e.textContent=t;e.style.bottom=document.querySelector('.bsheet.on')?'auto':'';e.style.top=document.querySelector('.bsheet.on')?'58px':'';e.classList.add('on');clearTimeout(toastT);toastT=setTimeout(()=>e.classList.remove('on'),1600)}

/* ---------- Navigation ---------- */
const TABS=['today','mind','body','soul','stats'];
const FULL={np:1,onb:1,set:1,lock:1,rprev:1,food:1,fadd:1,run:1,rend:1,torch:1,ci1:1,ci2:1,rate:1,eve:1,plan:1,planflow:1,review:1};
let cur='today',lastTab='today',navT=null;
let HIST=[];
function go(id,o={}){if(id==='planflow')return openNP('fill');if(id==='plan')return openNP('today');if(id==='review')return openNP('focus');
  if(id==='back'){id=HIST.pop()||lastTab;while(id===cur&&HIST.length)id=HIST.pop();if(id===cur)id=lastTab}else if(id!==cur){if(TABS.includes(id))HIST=[];else if(cur)HIST.push(cur)}
  if(id==='plan')id='today';
  if(id==='notif'){showNotif();return}
  closeSheet();
  const prev=cur,ti=TABS.indexOf(id),pi=TABS.indexOf(prev);
  const v=$('#v-'+id),ov=$('#v-'+prev);$$('.view').forEach(x=>{x.getAnimations().forEach(a=>a.cancel());x.classList.remove('on','leaving');x.style.zIndex=x.style.clipPath=''});
  $('#wonfx').classList.remove('on');$('#forfx').classList.remove('on');
  if(ov&&ov!==v)ov.classList.add('leaving');v.classList.add('on');cur=id;animView(v,ov!==v?ov:null,prev,id);if(ti>=0)lastTab=id;
  const nav=$('#tabbar');clearTimeout(navT);if(FULL[id])nav.classList.add('hide');else if(FULL[prev]&&!reduce)navT=setTimeout(()=>{if(!FULL[cur])nav.classList.remove('hide')},T_PAGE-40);else nav.classList.remove('hide');nav.classList.toggle('dark',id==='soul');
  $$('#tabbar button').forEach(b=>b.classList.toggle('on',b.dataset.go===(ti>=0?id:lastTab)));
  {const bg=getComputedStyle(v).backgroundColor;document.documentElement.style.setProperty('--pagebg',bg);const tc=document.querySelector('meta[name=theme-color]');if(tc)tc.content=bg}
  setTimeout(flameWake,60);if(id==='today'){countUp();growHome()}if(id==='mind'){radar();renderMplan();requestAnimationFrame(placeEW)}
  if(id==='soul'){renderQuest();skyDraw();$('#soulPct').textContent=PV('Soul')}
  if(id==='stats'){renderStats();requestAnimationFrame(renderStats)}
  if(id==='plan'){planMode='day';renderPlan();$$('#planSeg button')[0].click()}
  if(id==='planflow')startPF();
  if(id==='food')renderFood();
  if(id==='review')startRV();
  if(id==='lock')renderLock();
  if(id==='onb')startOb();
  if(id==='set')renderSet();
  flames.forEach(f=>f.dirty=true);
  setNotes(o.note||id);
}
/* ---------- Planning (night plan, This Week, Hero) — embedded from the planning prototype ---------- */
const NP_HTML="<title>Prometheus Night Plan<\/title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,100..900&display=swap\">\n<style>\n/* Layout: page tabs on top, one phone in the middle, short notes beside it. Single light look by choice (matches the v101 prototype); the night flow inside the phone is dark. */\n:root{\n  --bone:#ECE8E1; --paper:#FBFAF7; --stone:#D9D4CC; --grey:#AFA9A0; --ink:#17171A; --muted:#6F6A63;\n  --night:#17171A; --night2:#222226; --night3:#2C2C32; --nmut:#9B958C;\n  --ember:#FF4A1C; --cobalt:#2F5BEA; --gold:#FFB000; --green:#13A06F;\n  --f:\"Archivo\",\"Helvetica Neue\",Helvetica,Arial,sans-serif;\n  --ease:cubic-bezier(.2,.8,.2,1);\n  color-scheme:light;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:#DCD7CF;color:var(--ink)}\nbody{font-family:var(--f);font-size:15px;line-height:1.4}\nbutton{font-family:inherit;cursor:pointer;color:inherit}\nbutton:focus-visible,input:focus-visible{outline:2px solid var(--ember);outline-offset:2px}\n.lab{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;font-stretch:87%}\n.cond{font-stretch:62%;font-weight:800;text-transform:uppercase;line-height:.9}\n\n.page{max-width:1100px;margin:0 auto;padding-block:28px 56px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:grid;grid-template-columns:auto minmax(0,1fr);gap:28px;align-items:start}\n.head{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:end;justify-content:space-between;gap:14px 32px}\n.head h1{margin:0;font-stretch:62%;font-weight:800;font-size:clamp(40px,6vw,68px);line-height:.85;text-transform:uppercase}\n.head h1 em{font-style:normal;color:var(--ember)}\n.ptabs{display:flex;gap:4px;background:rgba(255,255,255,.45);border-radius:99px;padding:4px;flex-wrap:wrap}\n.ptabs button{all:unset;cursor:pointer;padding:8px 14px;border-radius:99px;font:600 13px var(--f);color:#3b3833}\n.ptabs button.on{background:var(--ink);color:#fff}\n.notes{background:var(--paper);border-radius:24px;padding:20px;display:flex;flex-direction:column;gap:10px;max-width:400px;min-width:0}\n.notes h2{margin:0;font-stretch:62%;font-weight:800;font-size:34px;line-height:.9;text-transform:uppercase}\n.notes p,.notes li{margin:0;font-size:13px;color:#45413c}\n.notes ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:5px}\n.restart{all:unset;cursor:pointer;align-self:flex-start;font:700 13px var(--f);padding:8px 14px;border-radius:99px;background:var(--bone)}\n\n.phone{width:340px;height:724px;max-width:100%;background:var(--bone);border-radius:48px;border:8px solid #111;box-shadow:0 50px 80px -40px rgba(0,0,0,.55);overflow:hidden;position:relative;isolation:isolate}\n@media (max-width:720px){.page{grid-template-columns:minmax(0,1fr)}.phone{margin:0 auto}.notes{max-width:none}}\n.view{position:absolute;inset:0;padding:54px 16px 20px;display:none;flex-direction:column;gap:12px;background:var(--bone);overflow:hidden}\n.view.on{display:flex;animation:vin .32s var(--ease)}\n@keyframes vin{from{opacity:0;transform:translateX(24px)}}\n.view.dark{background:var(--night);color:#fff}\n.top{display:flex;justify-content:space-between;align-items:center;min-height:32px;gap:10px}\n.back{all:unset;cursor:pointer;font:700 20px var(--f);width:32px;height:32px;display:grid;place-items:center;border-radius:50%;background:var(--night2);color:#fff}\n.light .back{background:var(--paper);color:var(--ink)}\n.ttl{font-size:44px}\n.sub{font-size:13px;color:var(--nmut)}\n.light .sub{color:var(--muted)}\n.btn{all:unset;box-sizing:border-box;cursor:pointer;text-align:center;border-radius:99px;padding:16px;font:700 15px var(--f);background:#fff;color:var(--ink);transition:transform .12s}\n.btn:active{transform:scale(.97)}\n.light .btn{background:var(--ink);color:#fff}\n.tlink{all:unset;cursor:pointer;font:700 13px var(--f);text-decoration:underline;text-underline-offset:3px;padding:6px 0;align-self:center}\n.grow{flex:1;min-height:0;overflow:auto;scrollbar-width:none;display:flex;flex-direction:column;gap:8px}\n.grow::-webkit-scrollbar{display:none}\n\n/* day strip */\n.strip{position:relative;height:30px;border-radius:8px;background:var(--night2);overflow:hidden;flex:none}\n.strip i{position:absolute;top:0;bottom:0}\n.strip .ev{background:#4a4a50}\n.strip .bk{opacity:.95}\n.strip .cur{border:2px solid #fff;border-radius:6px;background:rgba(255,255,255,.12);animation:pulse 1.6s ease-in-out infinite}\n@keyframes pulse{50%{background:rgba(255,255,255,.26)}}\n.ticks{display:flex;justify-content:space-between;font:600 10px var(--f);color:#6f6a62;margin-top:-6px}\n\n/* cal list */\n.crow{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:14px;background:var(--night2)}\n.crow .t{width:92px;flex:none;font:600 12px var(--f);color:var(--nmut);font-variant-numeric:tabular-nums}\n.crow b{flex:1;min-width:0;font:600 15px var(--f)}\n.crow small{font:600 12px var(--f);color:var(--nmut);white-space:nowrap}\n.crow.free{background:none;border:1.5px dashed #4a4a50}\n.crow.free b{color:#fff}\n.crow.blk{color:#fff}\n.crow.blk .t,.crow.blk small{color:rgba(255,255,255,.8)}\n.crow.blk.gold{color:var(--ink)}.crow.blk.gold .t,.crow.blk.gold small{color:rgba(0,0,0,.6)}\nbutton.crow{all:unset;box-sizing:border-box;cursor:pointer;display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:14px}\n.found{display:flex;gap:8px}\n.found div{flex:1;background:var(--night2);border-radius:16px;padding:10px 12px;display:flex;flex-direction:column}\n.found b{font:300 40px var(--f);font-stretch:75%;line-height:1;font-variant-numeric:tabular-nums}\n\n/* fill */\n.slothd{display:flex;flex-direction:column;gap:2px}\n.slothd .cond{font-size:40px}\n.q{font:700 17px var(--f);margin-top:4px}\n.opt{display:flex;align-items:stretch;gap:0;border-radius:18px;background:var(--night2);overflow:hidden;flex:none;transition:transform .12s}\n.opt:active{transform:scale(.98)}\n.opt .main{all:unset;cursor:pointer;flex:1;min-width:0;display:flex;align-items:center;gap:12px;padding:14px}\n.opt .sw{width:10px;align-self:stretch;border-radius:5px;flex:none}\n.opt .nm{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}\n.opt .nm b{font:600 16px var(--f);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.opt .nm small{font:500 12px var(--f);color:var(--nmut)}\n.opt .ed{all:unset;cursor:pointer;width:52px;display:grid;place-items:center;border-left:1px solid var(--night3);color:var(--nmut);font:600 12px var(--f)}\n.opt .ed:hover{color:#fff}\n.tag{font:700 9px var(--f);letter-spacing:.08em;text-transform:uppercase;border-radius:99px;padding:2px 7px;margin-right:6px;vertical-align:1px}\n.tag.goal{background:#fff;color:var(--ink)}\n.tag.focus{background:var(--night3);color:#fff}\n.tag.light{background:var(--bone);color:var(--ink)}\n.opt.other .main{color:#fff}\n.opt.other{background:none;border:1.5px dashed #4a4a50}\n.pdots{display:flex;gap:4px}\n.pdots i{width:18px;height:4px;border-radius:2px;background:var(--night3)}\n.pdots i.d{background:#fff}.pdots i.c{background:var(--ember)}\n\n/* goals coverage */\n.cov{display:flex;flex-wrap:wrap;gap:6px}\n.cov span{font:600 12px var(--f);border-radius:99px;padding:5px 10px;background:var(--night2);color:var(--nmut)}\n.cov span.ok{background:#fff;color:var(--ink)}\n\n/* quest */\n.qchip{all:unset;cursor:pointer;display:flex;align-items:center;gap:8px;background:var(--gold);color:var(--ink);border-radius:14px;padding:9px 12px;font:600 13px var(--f)}\n.qchip i{font-style:normal;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;opacity:.6}\n\n/* light screens */\n.light .card{background:var(--paper);border-radius:20px;padding:14px;display:flex;flex-direction:column;gap:10px}\n.chips{display:flex;flex-wrap:wrap;gap:6px}\n.chips button{all:unset;cursor:pointer;border-radius:99px;padding:8px 12px;font:600 13px var(--f);background:var(--bone);color:var(--ink);transition:background .2s,color .2s}\n.chips button.on{background:var(--c);color:#fff}\n.chips button.on.g{color:var(--ink)}\n.grow-h{display:flex;justify-content:space-between;align-items:baseline}\n.grow-h small{font:600 12px var(--f);color:var(--muted)}\n.grow-row{all:unset;box-sizing:border-box;cursor:pointer;width:100%;display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid var(--bone)}\n.grow-row:first-child{border-top:0}\n.grow-row .sw{width:10px;height:34px;border-radius:5px;flex:none}\n.grow-row span{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}\n.grow-row b{font:600 15px var(--f)}\n.grow-row small{font:500 12px var(--f);color:var(--muted)}\n.grow-row i{font-style:normal;color:var(--muted)}\n.grow-row .gm{flex:none;font:600 13px var(--f);color:var(--muted);font-variant-numeric:tabular-nums}\n.grow-row .sw{height:22px!important}\n.mini{height:4px;border-radius:2px;background:var(--bone);overflow:hidden;margin-top:4px}\n.mini i{display:block;height:100%;border-radius:2px}\n.herobox{all:unset;box-sizing:border-box;cursor:pointer;position:relative;overflow:hidden;background:var(--ink);color:#fff;border-radius:20px;padding:14px 16px;height:120px;display:flex;flex-direction:column;justify-content:space-between;flex:none;transition:transform .15s}\n.herobox:active{transform:scale(.98)}\n.herobox .cond{font-size:44px;color:var(--gold);position:relative;z-index:1}\n.herobox .hq{font:600 13px var(--f);position:relative;z-index:1}\n.herobox .hfill{position:absolute;left:0;bottom:0;right:0;background:var(--green);transition:height .6s var(--ease)}\n.hpanel{animation:vin .3s var(--ease)}\n.hqt{font:700 20px var(--f);line-height:1.15}\n.hdays{display:flex;gap:6px}\n.hdays i{flex:1;height:30px;border-radius:8px;background:var(--bone);display:grid;place-items:center;font:700 11px var(--f);font-style:normal;color:var(--muted)}\n.hdays i.d{background:var(--green);color:#fff}.hdays i.t{box-shadow:inset 0 0 0 2px var(--green);color:var(--ink)}\n.hlist{display:flex;flex-direction:column}\n.hlist button{all:unset;cursor:pointer;padding:12px 0;border-top:1px solid var(--bone);font:600 15px var(--f)}\n.hlist button.on{color:var(--green)}\n.hlist .lab{padding-top:10px;color:var(--muted)}\n.wkhero{all:unset;box-sizing:border-box;cursor:pointer;background:var(--green)!important;color:#fff;border-radius:20px;padding:14px;display:flex;flex-direction:column;gap:4px;flex:none}\n.wkhero .lab{color:rgba(255,255,255,.8)}.wkhero b{font:700 18px var(--f)}.wkhero:disabled{cursor:default}\n.hpills{display:flex;flex-wrap:wrap;gap:6px;align-items:center}\n.hpills button:not(.sq){all:unset;cursor:pointer;border-radius:99px;padding:9px 13px;font:600 13px var(--f);background:rgba(255,255,255,.2);color:#fff}\n.hpills button.on{background:#fff;color:var(--ink)}\n.hpills .sq{width:38px;height:38px}\n.hpills.frz button{opacity:.55;cursor:default}.hpills.frz button.on{opacity:1}\n.savebar{display:flex;gap:8px;align-items:center;flex:none}\n.savebar .btn{flex:1}\n.chips.frz button{cursor:default;opacity:.55}.chips.frz button.on{opacity:1}\n.addrow{all:unset;cursor:pointer;padding:12px 0 6px;font:700 13px var(--f);border-top:1px solid var(--bone)}\n.always{display:flex;flex-direction:column;gap:6px;font:500 13px var(--f);color:var(--muted)}\n.always b{color:var(--ink);font-weight:600}\n\n/* timeline */\n.donel{all:unset;cursor:pointer;font:700 13px var(--f);padding:8px 12px;border-radius:99px;background:var(--night2);color:#fff}\n.tlw{flex:1;min-height:0;overflow:auto;position:relative;background:var(--night2);border-radius:20px;scrollbar-width:none}\n.tlw::-webkit-scrollbar{display:none}\n.tlin{position:relative;margin:10px 0}\n.hr{position:absolute;left:0;right:0;border-top:1px solid var(--night3)}\n.hr span{position:absolute;left:8px;top:-7px;background:var(--night2);padding-right:4px;font:600 10px var(--f);color:#6f6a62}\n.tlin .ev,.tlin .fr,.tlin .bk{position:absolute;left:44px;right:8px;border-radius:9px;box-sizing:border-box}\n.tlin .ev{background:#3a3a40;color:#c9c2b8;padding:3px 10px;font:600 12px var(--f);overflow:hidden}\n.tlin .fr{border:1.5px dashed #45454b;transition:border-color .2s,background .2s}\n.tlin .mk{position:absolute;left:44px;right:8px;border:1.5px dashed #fff;border-radius:9px;background:rgba(255,255,255,.08);pointer-events:none;z-index:3;transition:top .15s var(--ease)}\n.tlin .mk.hot{border-color:var(--ember);background:rgba(255,74,28,.15)}\n.tlin .bk.mv{opacity:.85;z-index:4;box-shadow:0 8px 20px rgba(0,0,0,.5);transition:none}\n.tlin .bk{display:flex;align-items:center;gap:6px;padding:0 4px 0 10px;color:#fff;font:700 12px var(--f);cursor:pointer;overflow:hidden;transition:height .25s var(--ease),top .25s var(--ease);animation:bkin .25s var(--ease)}\n@keyframes bkin{from{opacity:0;transform:scale(.96)}}\n.tlin .bk.gold{color:var(--ink)}\n.tlin .bk b{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:700}\n.tlin .bk small{font:600 11px var(--f);opacity:.8;white-space:nowrap}\n.tlin .bk .x{all:unset;cursor:pointer;width:18px;height:18px;border-radius:50%;display:grid;place-items:center;font:700 10px var(--f);background:rgba(0,0,0,.18);flex:none}\n.tlin .bk.tall{align-items:flex-start;padding-top:5px}\n.tray,.tlw{-webkit-user-select:none;user-select:none}\n.tray{display:flex;flex-wrap:wrap;gap:6px;align-items:center;flex:none}\n.pill{all:unset;box-sizing:border-box;cursor:grab;border-radius:99px;padding:11px 14px;font:700 13px var(--f);color:#fff;background:var(--c);touch-action:none;user-select:none;-webkit-user-select:none;transition:transform .12s}\n.pill:active{transform:scale(.95)}\n.pill.g{color:var(--ink)}\n.sq{all:unset;cursor:pointer;width:42px;height:42px;border-radius:12px;background:#fff;color:var(--ink);display:grid;place-items:center;font:600 24px/1 var(--f);flex:none}\n.leave{all:unset;cursor:pointer;box-sizing:border-box;border:1.5px dashed #4a4a50;border-radius:99px;padding:10px 14px;font:700 13px var(--f);color:#fff}\n.qtray{flex-direction:column;align-items:stretch}\n.qtray .pill{border-radius:16px;white-space:normal;cursor:pointer;padding:14px 16px;font-size:15px}\n.qtray .leave{border-radius:16px;text-align:center;padding:14px}\n.ghost{position:absolute;z-index:50;pointer-events:none;opacity:.92;box-shadow:0 10px 24px rgba(0,0,0,.5);transform:scale(1.05)}\n.trayhint{font:600 12px var(--f);color:#6f6a62;width:100%}\n\n/* sheet */\n.scrim{position:absolute;inset:0;background:rgba(23,23,26,.5);z-index:25;opacity:0;pointer-events:none;transition:opacity .3s}\n.scrim.on{opacity:1;pointer-events:auto}\n.sheet{position:absolute;left:0;right:0;bottom:0;z-index:30;background:var(--paper);color:var(--ink);border-radius:30px 30px 0 0;padding:10px 18px 24px;display:flex;flex-direction:column;gap:12px;transform:translateY(105%);transition:transform .36s var(--ease);max-height:90%;overflow:auto}\n.sheet.on{transform:none}\n.grab{width:40px;height:5px;border-radius:3px;background:var(--stone);align-self:center;flex:none}\n.sheet h3{margin:0;font-stretch:62%;font-weight:800;font-size:28px;text-transform:uppercase;line-height:.95}\n.fld{display:flex;flex-direction:column;gap:6px}\n.fld>.lab{color:var(--muted)}\n.inp{border:0;border-radius:14px;background:var(--bone);padding:13px 14px;font:600 15px var(--f);color:var(--ink);outline:none;width:100%}\n.inp:focus{box-shadow:inset 0 0 0 2px var(--ink)}\n.seg{display:flex;background:var(--bone);border-radius:99px;padding:3px}\n.seg button{all:unset;cursor:pointer;flex:1;text-align:center;padding:8px 0;border-radius:99px;font:700 13px var(--f);color:var(--muted)}\n.seg button.on{background:var(--c,var(--ink));color:#fff}\n.lens{display:flex;flex-wrap:wrap;gap:6px}\n.lens button{all:unset;cursor:pointer;border-radius:12px;padding:9px 12px;font:700 13px var(--f);background:var(--bone)}\n.lens button.on{background:var(--ink);color:#fff}\n.lens button:disabled{opacity:.35;cursor:default}\n.stepper{display:flex;align-items:center;justify-content:space-between;background:var(--bone);border-radius:14px;padding:6px}\n.stepper b{font:800 22px var(--f);font-stretch:62%;font-variant-numeric:tabular-nums}\n.stepper button{all:unset;cursor:pointer;width:40px;height:40px;border-radius:50%;background:#fff;display:grid;place-items:center;font:700 18px var(--f)}\n.stepper button:disabled{opacity:.35;cursor:default}\n.shbtns{display:flex;gap:8px;align-items:center}\n.shbtns .btn{flex:1;background:var(--ink);color:#fff}\n.del{all:unset;cursor:pointer;font:700 13px var(--f);color:var(--ember);padding:10px 4px}\n.toast{position:absolute;left:50%;top:58px;transform:translate(-50%,-20px);opacity:0;background:#fff;color:var(--ink);border-radius:99px;padding:9px 14px;font:700 13px var(--f);z-index:40;transition:.3s var(--ease);white-space:nowrap;box-shadow:0 8px 20px rgba(0,0,0,.25)}\n.toast.on{opacity:1;transform:translate(-50%,0)}\n.lock{align-items:flex-start;justify-content:center;gap:14px}\n.lock .cond{font-size:64px}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n<\/style>\n\n<div class=\"page\">\n  <div class=\"head\">\n    <h1>Night <em>plan<\/em><\/h1>\n    <div class=\"ptabs\" id=\"ptabs\">\n      <button data-go=\"fill\" class=\"on\">Night plan<\/button>\n      <button data-go=\"focus\">Weekly focus<\/button>\n      <button data-go=\"goals\">Hero<\/button>\n    <\/div>\n  <\/div>\n\n  <div class=\"phone\" id=\"phone\">\n    <!-- 1. Tomorrow: timeline + pill tray -->\n    <section class=\"view dark\" id=\"v-fill\">\n      <div class=\"top\"><span class=\"cond\" style=\"font-size:32px\">Tomorrow<\/span><button class=\"donel\" id=\"toQuest\">Done \u203a<\/button><\/div>\n      <div class=\"tlw\" id=\"tl\"><\/div>\n      <div class=\"tray\" id=\"tray\"><\/div>\n    <\/section>\n\n    <!-- 2. Quest -->\n    <section class=\"view dark\" id=\"v-quest\">\n      <div class=\"top\"><button class=\"back\" data-back aria-label=\"Back\">\u2039<\/button><\/div>\n      <div class=\"cond ttl\">Quest<\/div>\n      <div class=\"tray qtray\" id=\"qopts\"><\/div>\n    <\/section>\n\n    <!-- 3. Review -->\n    <section class=\"view dark\" id=\"v-review\">\n      <div class=\"top\"><button class=\"back\" data-back aria-label=\"Back\">\u2039<\/button><button class=\"donel\" id=\"editPlan\">Edit<\/button><\/div>\n      <div class=\"cond\" style=\"font-size:32px\">Your plan<\/div>\n      <div id=\"rQuest\"><\/div>\n      <div class=\"tlw\" id=\"tlR\"><\/div>\n      <button class=\"btn\" id=\"lockIn\">Lock it in<\/button>\n    <\/section>\n\n    <!-- 5. Locked -->\n    <section class=\"view dark lock\" id=\"v-locked\">\n      <span class=\"cond\">Sleep<br>well.<\/span>\n      <button class=\"btn\" id=\"again\" style=\"align-self:stretch;margin-top:20px\">Go to home<\/button>\n    <\/section>\n\n    <!-- Weekly focus -->\n    <section class=\"view light\" id=\"v-focus\">\n      <div class=\"cond ttl\" style=\"margin-top:8px\">This Week<\/div>\n      <div class=\"grow\" id=\"focusBody\"><\/div>\n      <div class=\"savebar\" id=\"saveBar\"><\/div>\n    <\/section>\n\n    <!-- Goals -->\n    <section class=\"view light\" id=\"v-goals\">\n      <button class=\"herobox\" style=\"margin-top:8px\" id=\"heroBox\"><span class=\"cond\">Hero<\/span><span class=\"hq\" id=\"heroQ\"><\/span><span class=\"hfill\" id=\"heroFill\"><\/span><\/button>\n      <div class=\"grow\" id=\"heroPanels\" hidden>\n        <div class=\"card hpanel\"><div class=\"grow-h\"><span class=\"lab\" style=\"color:var(--green)\">Weekly Hero Quest<\/span><button class=\"tlink\" id=\"heroChange\" style=\"padding:0\">Change<\/button><\/div><b class=\"hqt\" id=\"hqTitle\"><\/b><div class=\"hdays\" id=\"hqDays\"><\/div><\/div>\n        <div class=\"card hpanel\"><span class=\"lab\" style=\"color:var(--green)\">Long-term goals<\/span><div id=\"goalList\"><\/div><\/div>\n      <\/div>\n    <\/section>\n\n    <div class=\"scrim\" id=\"scrim\"><\/div>\n    <div class=\"sheet\" id=\"sheet\"><\/div>\n    <div class=\"toast\" id=\"toast\"><\/div>\n  <\/div>\n\n  <aside class=\"notes\">\n    <h2 id=\"nT\">Night plan<\/h2>\n    <p id=\"nP\"><\/p>\n    <ul id=\"nL\"><\/ul>\n    <button class=\"restart\" id=\"reset\">Reset demo<\/button>\n  <\/aside>\n<\/div>\n\n<script>\nconst P={mind:{n:'Mind',c:'var(--cobalt)'},body:{n:'Body',c:'var(--ember)'},soul:{n:'Soul',c:'var(--gold)'},todo:{n:'To-do',c:'#6F6A63'}};\nconst LIB={\n  mind:{Chinese:[['TianTian app',30],['Tone review',15],['Conversation practice',30]],Reading:[['Read 20 pages',30],['Read a book chapter',60]],Writing:[['Write 500 words',30],['Edit a draft',60]],Classwork:[['Homework',60],['Reach out to professor',15]],Research:[['Deep-dive one topic',60],['Watch a lecture',60]],Skills:[['Chess puzzles',30],['Typing practice',15]],Music:[['Practice bass',30],['Learn a song',60]],Film:[['Break down a film',60],['Write a scene',60]],'Visual art':[['Sketch',30],['Color study',30]],Building:[['Ship one small feature',60],['Sketch an app idea',30]],Cooking:[['Cook a new recipe',60],['Meal-prep',60]],Meditation:[['Meditate',15],['Breathwork',15]],Journaling:[['Evening reflection',15],['Morning pages',15]],Social:[['Talk to a stranger',15]],Planning:[['Plan the week',30],['Budget check',15]]},\n  body:{Strength:[['Push day',60],['Pull day',60],['Leg day',60]],Run:[['Run 3 miles',30],['3K tempo run',30]],Bike:[['Ride 10 miles',60]],Swim:[['Swim 1K',30]],'Row / HIIT':[['20-min EMOM',30],['Row 5K',30]],Sport:[['Pickup basketball',60],['Climbing session',60]],Stretch:[['Yoga flow',30]],Mobility:[['Hip mobility',15]],Walk:[['Long walk',60],['Morning walk',30]],Sleep:[['Lights out by 11',15]]},\n  soul:{\"Order\": [\"Plan tomorrow in writing before bed\", \"Clear one cluttered space (desk, car, closet)\", \"Set up or reset your weekly calendar\", \"Fix one thing you've been putting off fixing\", \"Go through your finances for 20 minutes\", \"Clear your inbox or message backlog\", \"Write down your rules for one area of life (phone, money, mornings)\", \"Spend one full day on your planned schedule\"], \"Purpose\": [\"Write or revise your personal mission in one paragraph\", \"Review the past week: what moved you toward your goals, what didn't\", \"Pick the one priority for this month and write why it matters\", \"Write your eulogy as you'd want it read\", \"Cut one commitment that doesn't serve your purpose\", \"Imagine yourself 10 years from now and write a letter from them\", \"Check one decision this week against your values\", \"Spend 30 minutes thinking with no input (no phone, no music)\"], \"Blessing others\": [\"Tell someone specifically what they did well\", \"Help someone without being asked or telling anyone\", \"Teach someone a skill you have\", \"Write a thank-you note to someone who shaped you\", \"Introduce two people who should know each other\", \"Publicly credit someone else's work\", \"Ask someone what they need and follow through\", \"Forgive a small debt or grudge out loud\"], \"Discipline\": [\"Go to bed on time tonight\", \"Do your hardest task first, before anything else\", \"Take 3 swaps in one day\", \"Go the full day without your weakest-link habit\", \"Finish a workout exactly as planned, no shortcuts\", \"Cold shower\", \"Keep your phone out of the bedroom for a night\", \"Do a task to completion with no breaks to check your phone\"], \"Courage\": [\"Have a conversation you've been avoiding\", \"Say no to something you'd normally agree to out of guilt\", \"Share a piece of your writing with someone\", \"Ask for something you want (raise, favor, feedback)\", \"Admit a mistake to the person it affected\", \"Do something you're bad at in front of others\", \"Disagree honestly in a conversation\", \"Face one small fear on purpose and log what happened\"], \"Decisive action\": [\"Make a decision you've been stalling on, today\", \"Ship something unfinished but good enough\", \"Clear 5 small open tasks in one sitting\", \"Set a deadline and tell someone\", \"Cancel or quit something you've been half-doing\", \"Make a choice in under 2 minutes that you'd normally overthink\", \"Act today on an idea you had today\", \"Send the message you've been drafting in your head\"], \"Learning\": [\"Read for 30 minutes on a subject new to you\", \"Learn one thing and explain it to someone else\", \"Take notes on a book chapter in your own words\", \"Watch or attend a lecture and write 3 takeaways\", \"Ask an expert a question\", \"Learn the basics of a skill you've always dismissed\", \"Read something you expect to disagree with\", \"Review old notes and connect two ideas\"], \"Self-awareness\": [\"Shadow entry: who irritated you today, and where is that in you?\", \"Log a dream within 10 minutes of waking\", \"Persona audit: where did you act fake today, and why?\", \"Notice a strong emotion, name it, and trace where it came from\", \"Ask a trusted friend for one honest criticism\", \"Review this week's emotion check-ins and find a pattern\", \"Write a dialogue with a part of yourself you dislike (active imagination)\", \"Sit for 10 minutes and just watch your thoughts\"], \"Mastery\": [\"60 minutes of deliberate practice at your craft\", \"Study a master's work and copy their technique\", \"Redo a past piece better\", \"Get feedback on your work and apply one note\", \"Practice the part you're weakest at, not the fun part\", \"Set a measurable skill goal and test yourself against it\", \"Finish a small piece start to end in one sitting\", \"Teach or write about a technique you've learned\"], \"Connection\": [\"Call (not text) someone you care about\", \"Have a meal with someone, phones away\", \"Reach out to someone you've lost touch with\", \"Ask someone a deep question and just listen\", \"Plan something for someone you love\", \"Say \\\"I love you\\\" or \\\"I'm proud of you\\\" to someone\", \"Spend an hour with family with no agenda\", \"Make a new acquaintance\"], \"Presence\": [\"Meditate for 10 minutes\", \"Take a walk with no phone or headphones\", \"Eat one meal slowly, with no screens\", \"Spend 2 hours phone-free\", \"Watch a sunrise or sunset start to finish\", \"Do one ordinary task with full attention\", \"Spend time in nature for 30 minutes\", \"Do a body scan before sleep\"], \"Creativity\": [\"Make something with no goal of being good\", \"Try a creative medium you don't normally use\", \"Write for fun, not for a project\", \"Cook something without a recipe\", \"Play music, draw or sketch for 20 minutes\", \"Rearrange or redesign a space\", \"Go somewhere new and collect ideas\", \"Play: do something purely for enjoyment\"]}\n};\nlet EVENTS=[[9*60,10*60+15,'Film class'],[12*60+30,13*60+30,'Lunch with Maya'],[16*60,16*60+45,'Dentist'],[19*60,20*60,'Dinner at home']];\nconst WAKE=7*60,END=22*60+30,BUF=15,MIN=30,LENS=[15,30,45,60,90,120];\n\nlet S;\nfunction fresh(){\n  S={\n    focus:{mind:['Chinese','Writing'],body:['Strength','Run'],soul:['Courage','Presence']},\n    goals:[\n      {id:1,name:'Chinese',pillar:'mind',area:'Chinese',label:'TianTian app',len:30,freq:7,done:4},\n      {id:2,name:'Work',pillar:'todo',area:'',label:'Work',len:120,freq:5,done:3},\n      {id:3,name:'Strength',pillar:'body',area:'Strength',label:'Pull day',len:60,freq:3,done:2}\n    ],\n    hero:{name:'Run 5K every day',done:[1,1,1,0,0,0,0]},heroOpen:false,focusLocked:false,blocks:[],skipped:new Set(),_scrollNext:true,quest:null,questSet:false,asked:0,hist:[],view:'fill',nid:100,rot:0\n  };\n}\nfresh();\n\nconst $=s=>document.querySelector(s);\nfunction fmt(m){let h=Math.floor(m/60),mm=m%60,ap=h>=12?'pm':'am';h=h%12||12;return h+':'+String(mm).padStart(2,'0')+(ap==='pm'?'p':'a');}\nfunction fmtR(a,b){return fmt(a)+' \u2013 '+fmt(b);}\nfunction dur(m){const h=Math.floor(m/60),r=m%60;return h&&r?h+'h '+r+'m':h?h+'h':r+'m';}\nfunction freqTxt(g){return g.freq>=7?'Every day':g.freq+'\u00d7 a week';}\nfunction esc(s){return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));}\n\n/* free time */\nfunction baseGaps(){\n  const g=[];let cur=WAKE;\n  for(const [s,e] of EVENTS){const end=s-BUF;if(end-cur>=MIN)g.push([cur,end]);cur=Math.max(cur,e+BUF);}\n  if(END-cur>=MIN)g.push([cur,END]);return g;\n}\nfunction pieces(excludeId){\n  const out=[];\n  for(const [a,b] of baseGaps()){\n    let segs=[[a,b]];\n    for(const k of S.blocks){if(k.id===excludeId)continue;const ks=k.start,ke=k.start+k.len;\n      segs=segs.flatMap(([x,y])=>ke<=x||ks>=y?[[x,y]]:[[x,ks],[ke,y]].filter(([p,q])=>q>p));}\n    out.push(...segs.filter(([x,y])=>y-x>=15));\n  }\n  return out.sort((p,q)=>p[0]-q[0]);\n}\nfunction curPiece(){return pieces().find(p=>!S.skipped.has(p[0]+'-'+p[1]));}\nfunction prevEvent(t){let n='waking up';for(const [s,e,name] of EVENTS)if(e<=t)n=name;return n;}\n\n/* suggestions */\nfunction goalNeeds(g){return !S.blocks.some(b=>b.goalId===g.id)&&(g.freq>=7||g.done<g.freq);}\nfunction suggest(piece){\n  const r=piece[1]-piece[0],out=[];\n  const gs=S.goals.filter(g=>goalNeeds(g)&&g.len<=r).sort((a,b)=>(b.freq>=7)-(a.freq>=7)||(b.freq-b.done)-(a.freq-a.done));\n  gs.forEach(g=>out.push({name:g.label||g.name,area:g.area||g.name,pillar:g.pillar,len:g.len,tag:'goal',goalId:g.id,why:freqTxt(g)+(g.freq<7?' \u00b7 '+g.done+' of '+g.freq+' done':'')}));\n  const used=new Set([...S.blocks.map(b=>b.area),...out.map(o=>o.area)]);\n  const pool=[];\n  const m=S.focus.mind.filter(a=>!used.has(a)),bd=S.focus.body.filter(a=>!used.has(a));\n  for(let i=0;i<Math.max(m.length,bd.length);i++){if(m[i])pool.push(['mind',m[i]]);if(bd[i])pool.push(['body',bd[i]]);}\n  const off=pool.length?S.rot%pool.length:0;const rp=pool.slice(off).concat(pool.slice(0,off));\n  for(const [pl,a] of rp){const ideas=(LIB[pl][a]||[]);const idea=ideas.find(i=>i[1]<=r)||(ideas[0]?[ideas[0][0],Math.min(ideas[0][1],r)]:null);if(!idea)continue;\n    out.push({name:idea[0],area:a,pillar:pl,len:idea[1],tag:'focus',why:'This week\u2019s focus'});}\n  const names=new Set([...S.blocks.map(b=>b.name),...out.map(o=>o.name)]);\n  for(const pl of ['mind','body'])for(const a of S.focus[pl]){if(out.length>=3)break;\n    const idea=(LIB[pl][a]||[]).find(i=>i[1]<=r&&!names.has(i[0]));if(idea){names.add(idea[0]);out.push({name:idea[0],area:a,pillar:pl,len:idea[1],tag:'focus',why:'This week\u2019s focus'});}}\n  return out.slice(0,3);\n}\n\n/* views */\nconst HIST_VIEWS=['fill','quest','review','locked'];\nconst PX=1.2; // px per minute\nfunction go(v,push=true){\n  if(push&&S.view!==v)S.hist.push(S.view);\n  S.view=v;document.querySelectorAll('.view').forEach(e=>e.classList.toggle('on',e.id==='v-'+v));\n  document.querySelectorAll('#ptabs button').forEach(b=>b.classList.toggle('on',b.dataset.go===(HIST_VIEWS.includes(v)?'fill':v)));\n  render();notes();\n}\nfunction back(){const p=S.hist.pop();if(p)go(p,false);}\ndocument.querySelectorAll('[data-back]').forEach(b=>b.onclick=back);\ndocument.querySelectorAll('#ptabs button').forEach(b=>b.onclick=()=>{S.hist=[];go(b.dataset.go==='fill'?(S.lastFlow||'fill'):b.dataset.go,false);});\n\nconst Y=m=>(m-WAKE)*PX;\nfunction timeline(el,interactive){\n  const cur=interactive?curPiece():null;let h='';\n  for(let t=WAKE;t<=END;t+=60)h+=`<div class=\"hr\" style=\"top:${Y(t)}px\"><span>${fmt(t).replace(':00','')}<\/span><\/div>`;\n  EVENTS.forEach(([s,e,n])=>h+=`<div class=\"ev\" style=\"top:${Y(s)}px;height:${(e-s)*PX}px\">${n}<\/div>`);\n  if(interactive)pieces().forEach(p=>{h+=`<div class=\"fr\" style=\"top:${Y(p[0])}px;height:${(p[1]-p[0])*PX}px\"><\/div>`;});\n  if(cur)h+=`<div class=\"mk\" id=\"mk\" style=\"top:${Y(cur[0])}px;height:${15*PX}px\"><\/div>`;\n  S.blocks.forEach(b=>{const tall=b.len>=30;\n    h+=`<div class=\"bk ${b.pillar==='soul'?'gold':''} ${tall?'tall':''}\" data-b=\"${b.id}\" style=\"top:${Y(b.start)}px;height:${b.len*PX}px;background:${b.goalId?'var(--green)':P[b.pillar].c}\"><b>${esc(b.name)}<\/b><small>${dur(b.len)}<\/small>${interactive?`<button class=\"x\" data-x=\"${b.id}\" aria-label=\"Remove\">\u2715<\/button>`:''}<\/div>`;});\n  el.innerHTML=`<div class=\"tlin\" style=\"height:${(END-WAKE)*PX}px\">${h}<\/div>`;\n  if(interactive){\n    el.querySelectorAll('[data-b]').forEach(d=>moveBlock(d,+d.dataset.b));\n    el.querySelectorAll('[data-x]').forEach(d=>d.onclick=()=>{S.blocks=S.blocks.filter(b=>b.id!==+d.dataset.x);render();});\n    if(cur&&S._scrollNext){S._scrollNext=false;el.scrollTo({top:Math.max(0,Y(cur[0])-40),behavior:S._first?'smooth':'auto'});S._first=true;}\n  }\n}\n/* placed blocks: tap = stretch / shrink, drag = move (snaps to 15 min, only into free time) */\nfunction moveBlock(d,id){\n  let sy,drag=false,startTop,newStart=null;\n  d.addEventListener('pointerdown',e=>{if(e.target.dataset.x)return;sy=e.clientY;drag=false;startTop=parseFloat(d.style.top);d.setPointerCapture(e.pointerId);});\n  d.addEventListener('pointermove',e=>{\n    if(sy==null)return;const dy=e.clientY-sy;\n    if(!drag&&Math.abs(dy)>6){drag=true;d.classList.add('mv');}\n    if(!drag)return;\n    const b=S.blocks.find(x=>x.id===id);\n    let m=Math.round((((startTop+dy)/PX)+WAKE)/15)*15;\n    const p=pieces(id).find(p=>m+b.len>p[0]&&m<p[1]&&p[1]-p[0]>=b.len);\n    if(p){m=Math.max(p[0],Math.min(m,p[1]-b.len));newStart=m;d.style.top=Y(m)+'px';}\n  });\n  const end=()=>{if(sy==null)return;sy=null;d.classList.remove('mv');\n    if(drag){const b=S.blocks.find(x=>x.id===id);if(newStart!=null)b.start=newStart;newStart=null;render();}\n    else toggleFill(id);};\n  d.addEventListener('pointerup',end);\n  d.addEventListener('pointercancel',()=>{sy=null;newStart=null;render();});\n}\nfunction toggleFill(id){\n  const b=S.blocks.find(x=>x.id===id);\n  const p=pieces(id).find(p=>p[0]<=b.start&&p[1]>=b.start+b.len);\n  if(!p)return;\n  const full=p[1]-b.start;\n  if(b.len<full){b.len=full;}\n  else{b.len=15;}\n  render();\n}\n\nfunction render(){\n  document.querySelectorAll('#phone .ghost').forEach(g=>g.remove());\n  const v=S.view;\n  if(HIST_VIEWS.includes(v))S.lastFlow=v;\n  if(v==='fill'){\n    timeline($('#tl'),true);\n    const p=curPiece();const tray=$('#tray');\n    if(!p){tray.innerHTML=`<button class=\"btn\" id=\"nextQ\" style=\"flex:1\">Next<\/button>`;$('#nextQ').onclick=()=>go('quest');return;}\n    const sg=suggest(p);\n    tray.innerHTML=sg.map((o,i)=>`<button class=\"pill\" data-i=\"${i}\" style=\"--c:${o.goalId?'var(--green)':P[o.pillar].c}\">${esc(o.name)}<\/button>`).join('')\n      +`<button class=\"sq\" id=\"other\" aria-label=\"Other\">+<\/button><button class=\"leave\" id=\"leaveOpen\">Leave open<\/button>`;\n    tray.querySelectorAll('.pill').forEach(el=>dragPill(el,sg[+el.dataset.i]));\n    $('#other').onclick=()=>otherSheet(p);\n    $('#leaveOpen').onclick=()=>{S.skipped.add(p[0]+'-'+p[1]);S.rot++;S._scrollNext=true;render();};\n  }\n  if(v==='quest'){\n    const traits=S.focus.soul.length?S.focus.soul:['Courage'];const out=[];\n    for(let i=0;out.length<3&&i<8;i++){const t=traits[i%traits.length];const list=LIB.soul[t]||[];const q=list[(Math.floor(i/traits.length)+S.rot)%list.length];if(q&&!out.some(o=>o.name===q))out.push({name:q,trait:t});}\n    $('#qopts').innerHTML=out.map((o,i)=>`<button class=\"pill g\" data-q=\"${i}\" style=\"--c:var(--gold)\">${esc(o.name)}<\/button>`).join('')\n      +`<div style=\"display:flex;gap:6px\"><button class=\"sq\" id=\"qOther\" aria-label=\"Other\">+<\/button><button class=\"leave\" id=\"noQuest\" style=\"flex:1\">No quest<\/button><\/div>`;\n    $('#qopts').querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{S.quest=out[+b.dataset.q];go('review');});\n    $('#qOther').onclick=()=>questSheet({name:'',trait:traits[0]});\n    $('#noQuest').onclick=()=>{S.quest=null;go('review');};\n  }\n  if(v==='review'){\n    $('#rQuest').innerHTML=S.quest?`<button class=\"qchip\" id=\"rq\"><span>${esc(S.quest.name)}<\/span><\/button>`:'';\n    $('#rq')&&($('#rq').onclick=()=>go('quest'));\n    timeline($('#tlR'),false);\n    const first=S.blocks.length?Math.min(...S.blocks.map(b=>b.start)):WAKE;$('#tlR').scrollTop=Math.max(0,Y(first)-30);\n  }\n  if(v==='locked'){\n    const mins=S.blocks.reduce((a,b)=>a+b.len,0);const gl=S.goals.filter(g=>S.blocks.some(b=>b.goalId===g.id)).length;\n  }\n  if(v==='focus')renderFocus();\n  if(v==='goals')renderGoals();\n}\n\nfunction placeAt(o,start){\n  const p=pieces().find(p=>start>=p[0]&&start<p[1]);\n  if(!p){toast('No free time there');return false;}\n  if(start+15>p[1])start=p[1]-15;\n  if(start<p[0])return false;\n  S.blocks.push({id:++S.nid,name:o.name,area:o.area,pillar:o.pillar,len:15,start:start,goalId:o.goalId});\n  S.rot++;render();return true;\n}\n\n/* tap a pill = drop at the top of the highlighted slot. drag = drop where you let go. */\nfunction dragPill(el,o){\n  const phone=$('#phone');\n  function minuteAt(cy){const tl=$('#tl'),r=tl.getBoundingClientRect();if(cy<r.top||cy>r.bottom)return null;\n    const ir=tl.querySelector('.tlin').getBoundingClientRect();\n    return Math.round(((cy-ir.top)/PX+WAKE)/15)*15;}\n  el.addEventListener('dragstart',e=>e.preventDefault());\n  el.addEventListener('pointerdown',e=>{\n    if(e.button!==0)return;e.preventDefault();\n    const sx=e.clientX,sy=e.clientY;let drag=false,ghost=null,done=false;\n    const move=ev=>{\n      if(!drag&&Math.hypot(ev.clientX-sx,ev.clientY-sy)>6){drag=true;ghost=el.cloneNode(true);ghost.classList.add('ghost');phone.appendChild(ghost);}\n      if(!drag)return;\n      const pr=phone.getBoundingClientRect();ghost.style.left=(ev.clientX-pr.left-ghost.offsetWidth/2)+'px';ghost.style.top=(ev.clientY-pr.top-ghost.offsetHeight/2)+'px';\n      const m=minuteAt(ev.clientY),mk=$('#mk');if(!mk)return;\n      const p=m==null?null:pieces().find(p=>m>=p[0]&&m<p[1]);\n      if(p){mk.style.top=Y(Math.max(p[0],Math.min(m,p[1]-15)))+'px';mk.classList.add('hot');}\n      else{const c=curPiece();if(c)mk.style.top=Y(c[0])+'px';mk.classList.remove('hot');}\n    };\n    const finish=(ev,cancel)=>{\n      if(done)return;done=true;\n      window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',cx);window.removeEventListener('blur',cx);\n      document.querySelectorAll('#phone .ghost').forEach(g=>g.remove());\n      if(cancel){render();return;}\n      if(drag){const m=minuteAt(ev.clientY);if(m==null||!placeAt(o,m))render();}\n      else{const p=curPiece();if(p)placeAt(o,p[0]);}\n    };\n    const up=ev=>finish(ev,false),cx=ev=>finish(ev,true);\n    window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',cx);window.addEventListener('blur',cx);\n  });\n}\n$('#toQuest').onclick=()=>go('quest');\n$('#editPlan').onclick=()=>{S.skipped.clear();S._scrollNext=true;go('fill');};\n$('#lockIn').onclick=()=>go('locked');\n$('#again').onclick=()=>{toast('Home isn\\u2019t in this demo');setTimeout(()=>{fresh();go('fill',false);},900);};\n$('#reset').onclick=()=>{fresh();go('fill',false);};\n$('#heroBox').onclick=()=>{S.heroOpen=!S.heroOpen;renderGoals();};\n$('#heroChange').onclick=heroSheet;\n\n/* other */\nfunction otherSheet(piece){\n  let st={name:'',pillar:'mind',area:''};\n  function draw(){\n    const areas=st.pillar==='todo'?[]:Object.keys(LIB[st.pillar]);\n    $('#sheet').innerHTML=`<div class=\"grab\"><\/div><h3>Add Task<\/h3>\n      <div class=\"fld\"><input class=\"inp\" id=\"eName\" value=\"${esc(st.name)}\" placeholder=\"e.g. Call Mom\"><\/div>\n      <div class=\"fld\"><span class=\"lab\">Pillar<\/span><div class=\"seg\" id=\"ePil\">${['mind','body','todo'].map(k=>`<button data-k=\"${k}\" class=\"${st.pillar===k?'on':''}\" style=\"--c:${P[k].c}\">${P[k].n}<\/button>`).join('')}<\/div><\/div>\n      ${areas.length?`<div class=\"fld\"><span class=\"lab\">Area<\/span><div class=\"chips\" id=\"eArea\">${areas.map(a=>`<button data-a=\"${a}\" class=\"${st.area===a?'on':''}\" style=\"--c:${P[st.pillar].c}\">${a}<\/button>`).join('')}<\/div><\/div>`:''}\n      <div class=\"shbtns\"><button class=\"btn\" id=\"eSave\">Add<\/button><\/div>`;\n    $('#eName').oninput=e=>st.name=e.target.value;\n    $('#ePil').querySelectorAll('button').forEach(b=>b.onclick=()=>{st.pillar=b.dataset.k;st.area='';draw();});\n    $('#eArea')&&$('#eArea').querySelectorAll('button').forEach(b=>b.onclick=()=>{st.area=b.dataset.a;if(!st.name)st.name=(LIB[st.pillar][st.area][0]||[''])[0];draw();});\n    $('#eSave').onclick=()=>{const n=st.name.trim();if(!n){$('#eName').focus();return;}closeSheet();placeAt({name:n,area:st.area||n,pillar:st.pillar},piece[0]);};\n  }\n  draw();openSheet();\n}\nfunction questSheet(q){\n  let st={...q};\n  $('#sheet').innerHTML=`<div class=\"grab\"><\/div><h3>Quest<\/h3>\n    <div class=\"fld\"><input class=\"inp\" id=\"qName\" value=\"${esc(st.name)}\" placeholder=\"e.g. Call an old friend\"><\/div>\n    <div class=\"shbtns\"><button class=\"btn\" id=\"qSave\">Save<\/button><\/div>`;\n  $('#qSave').onclick=()=>{st.name=$('#qName').value.trim();if(!st.name){$('#qName').focus();return;}S.quest=st;closeSheet();go('review');};\n  openSheet();\n}\nfunction openSheet(){$('#scrim').classList.add('on');$('#sheet').classList.add('on');}\nfunction closeSheet(){$('#scrim').classList.remove('on');$('#sheet').classList.remove('on');}\n$('#scrim').onclick=closeSheet;\n\n/* weekly focus */\nfunction renderFocus(){\n  const h=['mind','body','soul'].map(pl=>`<div class=\"card\"><div class=\"grow-h\"><span class=\"lab\" style=\"color:${P[pl].c}\">${P[pl].n}<\/span><\/div>\n    <div class=\"chips ${S.focusLocked?'frz':''}\">${Object.keys(LIB[pl]).map(a=>`<button data-pl=\"${pl}\" data-a=\"${a}\" class=\"${pl==='soul'?'g ':''}${S.focus[pl].includes(a)?'on':''}\" style=\"--c:${P[pl].c}\">${a}<\/button>`).join('')}<\/div><\/div>`).join('')\n    +`<div class=\"card\"><div class=\"grow-h\"><span class=\"lab\" style=\"color:var(--green)\">Weekly Hero Quest<\/span><\/div><div class=\"chips ${S.focusLocked?'frz':''}\">${heroOpts().map(n=>`<button data-hp=\"${esc(n)}\" class=\"${S.hero.name===n?'on':''}\" style=\"--c:var(--green)\">${esc(n)}<\/button>`).join('')}<button id=\"hOwn\">+ Your own<\/button><\/div><\/div>`;\n  $('#focusBody').innerHTML=h;\n  $('#focusBody').querySelectorAll('[data-hp]').forEach(b=>b.onclick=()=>{if(S.focusLocked)return;setHero(b.dataset.hp);});\n  $('#hOwn').onclick=()=>{if(!S.focusLocked)heroOwn();};\n  $('#focusBody').querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{if(S.focusLocked)return;const l=S.focus[b.dataset.pl],a=b.dataset.a,i=l.indexOf(a);i>=0?l.splice(i,1):l.push(a);renderFocus();});\n  $('#saveBar').innerHTML=S.focusLocked?`<button class=\"btn\" id=\"fEdit\" style=\"background:var(--paper);color:var(--ink)\">Locked \u00b7 Edit<\/button>`:`<button class=\"btn\" id=\"fSave\">Save<\/button>`;\n  $('#fSave')&&($('#fSave').onclick=()=>{S.focusLocked=true;renderFocus();toast('Saved');});\n  $('#fEdit')&&($('#fEdit').onclick=()=>{S.focusLocked=false;renderFocus();});\n}\n\n/* hero */\nconst HEROES={Mind:['Finish a book this week','Write 3,500 words this week','Learn and play one full song','No social media for 7 days'],Body:['Run 5K every day','Train 60 minutes every day','10,000 steps every day','Sleep 7h+ every night','No coffee for 7 days'],Soul:['Have the hard conversation','No phone after 9 pm, all week','Call a different person every day','Say yes to one thing that scares you']};\nfunction heroOpts(){const r=S.heroRot||0;const o=['Mind','Body','Soul'].map((k,i)=>HEROES[k][(r+i)%HEROES[k].length]);if(!o.includes(S.hero.name))o[0]=S.hero.name;return o;}\nfunction setHero(n){S.hero={name:n,done:S.hero.name===n?S.hero.done:[0,0,0,0,0,0,0]};render();}\nfunction heroOwn(){\n  $('#sheet').innerHTML=`<div class=\"grab\"><\/div><h3>Hero Quest<\/h3><div class=\"fld\"><input class=\"inp\" id=\"hName\" placeholder=\"Type your own\"><\/div><div class=\"shbtns\"><button class=\"btn\" id=\"hSave\">Save<\/button><\/div>`;\n  $('#hSave').onclick=()=>{const n=$('#hName').value.trim();if(!n){$('#hName').focus();return;}closeSheet();setHero(n);};\n  openSheet();setTimeout(()=>$('#hName').focus(),350);\n}\nfunction heroSheet(){\n  $('#sheet').innerHTML=`<div class=\"grab\"><\/div><h3>Hero Quest<\/h3><div class=\"hlist\">${heroOpts().map(n=>`<button class=\"${S.hero.name===n?'on':''}\" data-h=\"${esc(n)}\">${esc(n)}<\/button>`).join('')}<\/div><div class=\"fld\"><input class=\"inp\" id=\"hName\" placeholder=\"Type your own\"><\/div><div class=\"shbtns\"><button class=\"btn\" id=\"hSave\">Save<\/button><\/div>`;\n  $('#sheet').querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{closeSheet();setHero(b.dataset.h);});\n  $('#hSave').onclick=()=>{const n=$('#hName').value.trim();if(!n){$('#hName').focus();return;}closeSheet();setHero(n);};\n  openSheet();\n}\n/* goals */\nfunction renderGoals(){\n  const days='MTWTFSS'.split(''),h=S.hero;\n  $('#heroQ').textContent=h.name+' \u00b7 '+h.done.filter(Boolean).length+'/7';\n  $('#heroFill').style.height=(h.done.filter(Boolean).length/7*100)+'%';\n  $('#heroPanels').hidden=!S.heroOpen;\n  $('#hqTitle').textContent=h.name;\n  $('#hqDays').innerHTML=days.map((d,i)=>`<i class=\"${h.done[i]?'d':i===3?'t':''}\">${h.done[i]?'\u2713':d}<\/i>`).join('');\n  $('#goalList').innerHTML=S.goals.map(g=>`<button class=\"grow-row\" data-g=\"${g.id}\"><span class=\"sw\" style=\"background:var(--green)\"><\/span><span><b>${esc(g.name)}<\/b><\/span><small class=\"gm\">${dur(g.len)} \u00b7 ${g.freq>=7?'Daily':g.freq+'\u00d7/wk'}<\/small><\/button>`).join('')\n    +`<button class=\"addrow\" id=\"gNew\" style=\"display:block;width:100%\">+ New goal<\/button>`;\n  $('#goalList').querySelectorAll('[data-g]').forEach(b=>b.onclick=()=>goalSheet(S.goals.find(g=>g.id==b.dataset.g)));\n  $('#gNew').onclick=()=>goalSheet(null);\n}\nfunction goalSheet(g){\n  const isNew=!g;let st=g?{...g}:{id:++S.nid,name:'',pillar:'mind',area:'',label:'',len:30,freq:7,done:0};\n  function draw(){\n    const areas=st.pillar==='todo'?[]:Object.keys(LIB[st.pillar]);\n    $('#sheet').innerHTML=`<div class=\"grab\"><\/div><h3>${isNew?'New goal':'Edit goal'}<\/h3>\n      <div class=\"fld\"><input class=\"inp\" id=\"gName\" value=\"${esc(st.name)}\" placeholder=\"e.g. Study Chinese\"><\/div>\n      <div class=\"fld\"><span class=\"lab\">Pillar<\/span><div class=\"seg\" id=\"gPil\">${['mind','body','todo'].map(k=>`<button data-k=\"${k}\" class=\"${st.pillar===k?'on':''}\" style=\"--c:${P[k].c}\">${P[k].n}<\/button>`).join('')}<\/div><\/div>\n      ${areas.length?`<div class=\"fld\"><span class=\"lab\">Area<\/span><div class=\"chips\" id=\"gArea\">${areas.map(a=>`<button data-a=\"${a}\" class=\"${st.area===a?'on':''}\" style=\"--c:${P[st.pillar].c}\">${a}<\/button>`).join('')}<\/div><\/div>`:''}\n      <div class=\"fld\"><span class=\"lab\">Length<\/span><div class=\"lens\" id=\"gLen\">${LENS.map(l=>`<button data-l=\"${l}\" class=\"${st.len===l?'on':''}\">${dur(l)}<\/button>`).join('')}<\/div><\/div>\n      <div class=\"fld\"><span class=\"lab\">How often<\/span><div class=\"seg\" id=\"gF\"><button data-f=\"d\" class=\"${st.freq>=7?'on':''}\">Every day<\/button><button data-f=\"w\" class=\"${st.freq<7?'on':''}\">Times a week<\/button><\/div>\n        ${st.freq<7?`<div class=\"stepper\"><button id=\"fM\" ${st.freq<=1?'disabled':''}>\u2212<\/button><b>${st.freq}\u00d7 a week<\/b><button id=\"fP\" ${st.freq>=6?'disabled':''}>+<\/button><\/div>`:''}<\/div>\n      <div class=\"shbtns\">${isNew?'':'<button class=\"del\" id=\"gDel\">Delete<\/button>'}<button class=\"btn\" id=\"gSave\">Save<\/button><\/div>`;\n    $('#gName').oninput=e=>st.name=e.target.value;\n    $('#gPil').querySelectorAll('button').forEach(b=>b.onclick=()=>{st.pillar=b.dataset.k;st.area='';draw();});\n    $('#gArea')&&$('#gArea').querySelectorAll('button').forEach(b=>b.onclick=()=>{st.area=b.dataset.a;if(!st.name)st.name=st.area;draw();});\n    $('#gLen').querySelectorAll('button').forEach(b=>b.onclick=()=>{st.len=+b.dataset.l;draw();});\n    $('#gF').querySelectorAll('button').forEach(b=>b.onclick=()=>{st.freq=b.dataset.f==='d'?7:(st.freq>=7?5:st.freq);draw();});\n    $('#fM')&&($('#fM').onclick=()=>{st.freq--;draw();});$('#fP')&&($('#fP').onclick=()=>{st.freq++;draw();});\n    $('#gSave').onclick=()=>{st.name=st.name.trim();if(!st.name){$('#gName').focus();return;}if(!st.label||isNew)st.label=st.area?((LIB[st.pillar][st.area]||[[st.name]])[0][0]):st.name;\n      if(isNew)S.goals.push(st);else Object.assign(S.goals.find(x=>x.id===st.id),st);closeSheet();renderGoals();toast('Goal saved');};\n    $('#gDel')&&($('#gDel').onclick=()=>{S.goals=S.goals.filter(x=>x.id!==st.id);closeSheet();renderGoals();toast('Goal deleted');});\n  }\n  draw();openSheet();\n}\n\nlet tt;function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('on');clearTimeout(tt);tt=setTimeout(()=>e.classList.remove('on'),1600);}\n\n/* notes */\nconst NOTES={\n  fill:['Tomorrow','Close the day ends here. Your calendar is the screen. The white 15-min marker shows where the next pill lands.',['Pills fit the current free slot: long-term goals first, then this week\u2019s focus.','Tap a pill to drop it at the top of the slot, or drag it anywhere free.','Every block starts at 15 min. Tap it once to stretch it to the next thing. Tap again to shrink it back. Drag a placed block to move it.','\u2715 removes a block. + adds something else. Leave open moves to the next slot.','Free time = gaps of 30 min or more, with 15 min around each event.']],\n  quest:['Quest','One all-day quest from this week\u2019s Soul focus. It never takes a slot.',[]],\n  review:['Review','Tomorrow at a glance. Chips show which long-term goals made it in.',['Edit goes back to the timeline.']],\n  locked:['Locked','Tomorrow shows on Today when you wake up.',[]],\n  focus:['Weekly focus','Picked in the Sunday review. Areas only, no numbers.',['Every area and trait is listed. Tap any to add or remove it, then Save to lock the week.','Weekly Hero Quest: 3 suggestions (one per pillar) or + to type your own.','Long-term goals moved to Hero.']],\n  goals:['Hero','Tap the Hero box (as on Home) to open its two panels.',['Weekly Hero Quest: one per week, tracked by day. Change offers 3 suggestions or type your own.','Long-term goals live here now (Settings page removed). They stay green everywhere: tray pills and timeline blocks.','Long-term goals are offered first in any free slot they fit.']]\n};\nfunction notes(){const n=NOTES[S.view];$('#nT').textContent=n[0];$('#nP').textContent=n[1];$('#nL').innerHTML=n[2].map(x=>`<li>${x}<\/li>`).join('');}\ngo('fill',false);\n<\/script>\n\n\n";
