const T_TAP=200,T_PAGE=380,T_MOM=700,EZ='cubic-bezier(.2,.8,.2,1)';
const FLOWG={np:'np',ci1:'ci',ci2:'ci',rate:'ci',eve:'ci',review:'review',planflow:'planflow',rprev:'run',run:'run',rend:'run',fadd:'fadd'};
const FORDER=['rprev','run','rend','eve','ci1','ci2','rate','planflow'];
