  if(b){const [k,d]=b.dataset.st.split('|'),cur=E.sets.findIndex(s=>!s.d),st=k==='w'?5:E.u?5:1;E.sets.forEach((s,j)=>{if(j>=cur&&!s.d)s[k]=Math.max(k==='w'?0:1,s[k]+d*st)});renderRun();return}
