{let x0=null;$('#rnMain').addEventListener('pointerdown',e=>{x0=e.clientX});$('#rnMain').addEventListener('pointerup',e=>{if(x0==null)return;const dx=e.clientX-x0;x0=null;if(Math.abs(dx)>50)slideTo(RUN.i+(dx<0?1:-1))})}
