const mx=(n,k,p,c,f)=>[n,k,p??Math.round(k*.25/4),c??Math.round(k*.45/4),f??Math.round(k*.3/9)];
const FLOG={Breakfast:[],Lunch:[],Dinner:[],Snack:[]};
