function parseArea(n,p){const ar=(obSel[p]||[]).find(a=>n===a||n.startsWith(a+' · '));if(ar)return [ar,n.slice(ar.length+3)||null];const all=(obSel[p]||[]).find(a=>areaIdeas(p,a).includes(n));return all?[all,n]:[null,n]}
