const CORN=[{n:'Wired',c:'var(--ember)',t:'#fff',tag:['#FFE2D9','#C2300B'],sl:'var(--ember)',w:'Stressed Anxious Frustrated Irritated Overwhelmed Nervous Tense Restless Annoyed Worried Angry Pressured Jittery Agitated Impatient On edge Fed up Defensive Panicked Scared Jealous Embarrassed Shocked Furious'},
 {n:'Bright',c:'var(--gold)',t:'var(--ink)',tag:['#FFF0C7','#8A5E00'],sl:'var(--gold)',w:'Excited Proud Joyful Energized Inspired Motivated Confident Playful Optimistic Thrilled Eager Focused Hopeful Cheerful Lively Amused Determined Upbeat Elated Curious Pumped Accomplished Alive Surprised'},
 {n:'Spent',c:'var(--cobalt)',t:'#fff',tag:['#DCE4FC','#1F43B8'],sl:'var(--cobalt)',w:'Tired Drained Down Bored Sad Lonely Disappointed Numb Discouraged Sluggish Exhausted Meh Hurt Guilty Lost Gloomy Burned out Empty Unmotivated Insecure Left out Apathetic Ashamed Hopeless'},
 {n:'Easy',c:'var(--green)',t:'#fff',tag:['#D6F2E6','#0B6E4B'],sl:'var(--green)',w:'Calm Content Relaxed Grateful Peaceful Rested Grounded Thoughtful Satisfied Mellow Balanced Comfortable At ease Chill Fulfilled Secure Serene Cozy Relieved Patient Reflective Easygoing Tranquil Blessed'}];
const splitW=s=>s.replace(/On edge|Fed up|Burned out|Left out|At ease/g,m=>m.replace(' ','_')).split(' ').map(x=>x.replace('_',' '));
let corner=1;
const EWP=[[-1,-1],[1,-1],[-1,1],[1,1]];
const EWS=[[0,[255,138,14]],[45,[255,176,0]],[90,[141,187,46]],[135,[19,160,111]],[225,[47,91,234]],[315,[255,74,28]],[360,[255,138,14]]],EWB=[217,212,204];
const ewMix=(a,b,t)=>a.map((v,i)=>Math.round(v+(b[i]-v)*t));
function ewAt(d){for(let i=0;i<EWS.length-1;i++){const [a,ca]=EWS[i],[b,cb]=EWS[i+1];if(d>=a&&d<=b)return ewMix(ca,cb,(d-a)/(b-a))}return EWS[0][1]}
function placeEW(){const h=$('#ewh');if(!h)return;const W=h.clientWidth||300,cx=W/2,cy=83,r=67;
  $$('#ewh .ewn').forEach(b=>{const [x,y]=EWP[+b.dataset.corner];b.style.left=(cx+x*r*.7071)+'px';b.style.top=(cy+y*r*.7071)+'px'});
  const tot=CHK[0]+CHK[1]+CHK[2]+CHK[3];let col=EWB;
  if(tot){let x=0,y=0;[0,1,2,3].forEach(k=>{x+=EWP[k][0]*CHK[k];y+=-EWP[k][1]*CHK[k]});x/=tot;y/=tot;
    const m=Math.min(1,Math.hypot(x,y)/Math.SQRT2);let d=Math.atan2(x,y)*180/Math.PI;if(d<0)d+=360;{const nd=Math.round((d-45)/90)*90+45;d=((nd+(d-nd)*.4)+360)%360}col=ewMix(EWB,ewAt(d),Math.min(1,m*4))}
  const c=$('#ewC');c.style.setProperty('--avg',`rgb(${col})`)}
$('#ewC').onclick=()=>go('ci1');
$$('#ewh .ewn').forEach(b=>b.onclick=()=>{corner=+b.dataset.corner;b.animate([{transform:'scale(.85)'},{transform:'scale(1)'}],{duration:200});setTimeout(()=>openWords(),140)});
$$('.meter button').forEach(b=>b.onclick=()=>{corner=+b.dataset.corner;b.animate([{transform:'scale(.95)'},{transform:'scale(1)'}],{duration:200});setTimeout(()=>openWords(),140)});
function openWords(){const c=CORN[corner];$('#ci2Back').textContent='← '+c.n;const w=$('#words');w.style.setProperty('--wc',c.c);w.style.setProperty('--wt',c.t);
  w.innerHTML=splitW(c.w).map((x,i)=>`<button style="animation-delay:${i*14}ms">${x}</button>`).join('');go('ci2')}
$('#words').onclick=e=>{const b=e.target.closest('button');if(!b)return;$$('#words button').forEach(x=>x.classList.remove('on'));b.classList.add('on');const c=CORN[corner];
  $('#ciWord').textContent=b.textContent;$('#ciTag').textContent=c.n;$('#ciTag').style.background=c.tag[0];$('#ciTag').style.color=c.tag[1];setTimeout(()=>openSheet('ci3'),160)};
$$('.track').forEach(tr=>{const set=e=>{const r=tr.getBoundingClientRect(),p=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),v=1+Math.round(p*4),q=(v-1)*25;tr.querySelector('i').style.width=q+'%';tr.querySelector('em').style.left=q+'%';$('#sv'+tr.dataset.i).textContent=v};
  tr.addEventListener('pointerdown',e=>{tr.setPointerCapture(e.pointerId);set(e);tr.onpointermove=set});tr.addEventListener('pointerup',()=>tr.onpointermove=null)});
let EMOFORCE=false;
$('#ciSave').onclick=()=>{const st=+$('#sv1').textContent,dr=+$('#sv0').textContent;CHK[corner]++;CHKW.done++;D.checkins.push({t:Date.now(),d:TODAY,c:corner,w:$('#ciWord').textContent,st,dr});D.lastCheckin=Date.now();save();closeSheet();go(lastTab);setTimeout(()=>{placeEW();openEmo(st,dr,corner)},420)};
function openEmo(st,dr,c){const force=st>=4||dr<=1||dr>=5;if(!force)return;let k,lab,ttl,list;
  if(st>=4){k='Stress';lab=`Stress ${st}/5`;ttl='Bring it down';list=EMO.Stress}
  else if(dr<=1){k='Drive';lab=`Drive ${dr}/5`;ttl='Lift it up';list=EMO.Drive}
  else{k='Stability';lab=`Drive ${dr}/5 · running hot`;ttl='Hold steady';list=[['Wind down early tonight',.5],['Protect sleep: lights out on time',.25],['Hold big decisions for 24h',.083],['Phone out of the bedroom',.083],...EMO.Stability]}
  EMOFORCE=force;const ai=axes.findIndex(a=>a.it[0]===k);
  $('#emLab').textContent=lab+(force?' · pick one':'');$('#emTtl').textContent=ttl;$('#emLater').style.display=force?'none':'';
  $('#emList').innerHTML=qMix(list.map(([n,d],j)=>`<div class="qrow"><div><b>${esc(n)}</b><small>${dlab(d)}</small></div><button class="qplus" data-em="${j}" aria-label="Add ${esc(n)}">+</button></div>`));
  const add=(n,d)=>{if(!THREE.some(x=>x[0]===n))THREE.push([n,'Mind',null,d,false,ai]);axes[ai].it[2]++;EMOFORCE=false;closeSheet();setTimeout(()=>{openNP('today');toast(force?'Place it now':'Added · place it in today')},250)};
  $('#emList').onclick=e=>{if(e.target.closest('[data-own]')){const inp=$('#emList .qin'),v=inp.value.trim();if(!v){inp.focus();return}add(v,.167);return}const b=e.target.closest('[data-em]');if(b){const [n,d]=list[+b.dataset.em];add(n,d)}};
  openSheet('emo');$('#emList').scrollTop=0}
$('#emLater').onclick=()=>{EMOFORCE=false;closeSheet()};

