/* a11y: tappable non-buttons get role, focus and keys */
const NATIVE=/^(BUTTON|A|INPUT|SELECT|TEXTAREA|LABEL|OPTION)$/;
function a11yPass(){$$('#phone [data-go],#phone [data-w],#phone [data-t],#phone [data-k],#phone [data-ck],#phone [data-pa],#phone [data-pl],#phone [data-m],#phone [data-hf],#phone [data-em],#phone [data-own],#phone [data-corner],#hSpoil,#phone .aev,#phone .wkd').forEach(el=>{
  if(NATIVE.test(el.tagName)||el.closest('button')||el.hasAttribute('role'))return;if(getComputedStyle(el).pointerEvents==='none')return;
  el.setAttribute('role','button');el.tabIndex=0;if(!el.textContent.trim()&&!el.getAttribute('aria-label')){const l=el.dataset.m||el.dataset.hf||el.dataset.go||'';if(l)el.setAttribute('aria-label',l)}})}
function noAuto(root){root.querySelectorAll('input:not([type=file]):not([data-na]),textarea:not([data-na])').forEach(i=>{i.setAttribute('autocomplete','off');i.setAttribute('autocorrect','off');i.setAttribute('autocapitalize','sentences');i.setAttribute('data-form-type','other');i.setAttribute('data-lpignore','true');i.name='p'+Math.random().toString(36).slice(2,8);i.dataset.na=1})}
noAuto(document);
let a11yT;new MutationObserver(()=>{clearTimeout(a11yT);a11yT=setTimeout(()=>{a11yPass();noAuto(document)},120)}).observe($('#phone'),{childList:true,subtree:true});a11yPass();
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.getAttribute&&e.target.getAttribute('role')==='button'&&!NATIVE.test(e.target.tagName)){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
